#[summary("impossibility certificate")]
mod bmb_cert {
    spec fn never() -> bool { false }

    spec fn witness(x: i64) -> bool { x == -1 }

    #[effects(pure)]
    #[uses(witness, tasks::same_value)]
    fn refute(x: i64) -> ()
        requires witness(x),
        ensures never(),
    {
        let r: u64 = tasks::to_u64(x);
    }

    #[effects(pure)]
    #[uses(witness)]
    fn reach() -> () {
        refute(-1)
    }
}

